#!/bin/bash
#-----------------------------------------------------------------------------
# Title      : Add yosys_synth.mk to the Makefile generated by edalize
# Project    : Asylum
#-----------------------------------------------------------------------------
# File       : yosys_synth.sh
# Author     : mrosiere
#-----------------------------------------------------------------------------
# Description: pre_run hook of the syn_* targets (cwd = fusesoc work_root,
#              Makefile generated by edalize at setup), same scheme as
#              ghdl_synth.sh. Appends "include yosys_synth.mk" to the
#              Makefile (once): the run step (make run EXTRA_OPTIONS=<generics
#              of the target>) then synthesizes the toplevel with Yosys
#              before ghdl -r. See yosys_synth.mk.
#-----------------------------------------------------------------------------
# Copyright (c) 2026
#-----------------------------------------------------------------------------
# Revisions  :
# Date        Version  Author   Description
# 2026-11-20  1.0      mrosiere Created
#-----------------------------------------------------------------------------

MAKEFILE=Makefile
MK=yosys_synth.mk

for file in "$MAKEFILE" "$MK";
do
    if [ ! -f "$file" ];
    then
        echo "yosys_synth.sh : $file not found in $PWD" >&2
        exit 1
    fi
done

if ! grep -qx "include $MK" "$MAKEFILE";
then
    printf '\n# Added by yosys_synth.sh (pre_run hook)\ninclude %s\n' "$MK" >> "$MAKEFILE"
fi
